export declare function patchXcodeProject(opts: PatchXcodeOptions): boolean;
export declare function patchXcodeProjectForNotifyKitNse(proj: XcodeProject, options: NotifyKitNseXcodePatchOptions): NotifyKitNseXcodePatchResult;
